function makeTranslation(copy) {
  return {
    meta: copy.meta,
    eyebrow: copy.eyebrow,
    h1: copy.h1,
    intro: copy.intro,
    answerLabel: copy.answerLabel,
    answer: copy.answer,
    tocLabel: copy.tocLabel,
    tocFaq: copy.tocFaq,
    heroImage: { ...visualCopy.coop, alt: copy.heroImage.alt, caption: copy.heroImage.caption },
    sections: copy.sections,
    faq: { eyebrow: copy.faq.eyebrow, title: copy.faq.title, items: copy.faq.items },
    source: { eyebrow: copy.source.eyebrow, title: copy.source.title, body: copy.source.body, links: copy.source.links },
    related: copy.related,
    relatedLabel: copy.relatedLabel,
  };
}

